  published = excluded.published;

insert into public.premium_content
  (slug, title, category, required_entitlement, teaser, content, published)
values (
  'data-engineer-pipeline',
  'Build a Reliable Batch + Streaming Data Pipeline (Data Engineer)',
  'data-engineer',
  'system_design_pro',
  '{"setup":"You''re the data engineer. The business needs trustworthy analytics tables fed by both nightly batch and near-real-time events on a lakehouse (Databricks/Spark). Design the pipeline and defend the calls under pressure — ingestion, ETL/ELT, data quality, and cost.","you_will_practice":["Batch + streaming ingestion on a lakehouse","ELT vs ETL and idempotent, incremental loads","Data-quality checks and schema evolution","Spark performance and pipeline cost control"],"node_titles":["Approach","Batch vs streaming","ELT vs ETL","Idempotency & backfill","Data quality","Schema evolution","Spark performance","Incident: late data","Reflection","Next"],"sample_node":{"id":"n3","kind":"why","prompt":"Why ELT into the lakehouse rather than transforming before load (classic ETL)?","model":"Landing raw first keeps an immutable, replayable source of truth: you can reprocess when logic changes without re-ingesting, and transformations run on elastic lakehouse compute (Spark/SQL) close to the data. Trade-off: raw storage cost and governance over a larger surface. For heavy pre-load cleansing or strict PII-at-source rules you''d still transform-on-ingest, accepting less replayability.","signals":["raw landing = replayable source of truth","transform on elastic compute near the data","names when ETL-on-ingest still wins + the trade-off"]}}'::jsonb,
  '{"start":"n1","nodes":{"n1":{"id":"n1","kind":"decision","prompt":"Clarify first, then give your one-paragraph design for analytics tables fed by nightly batch and near-real-time events.","model":"Clarify: data volume/velocity, freshness SLO per table, event ordering/duplicates, PII, and the cost ceiling. Design: a layered lakehouse (bronze raw → silver cleaned/conformed → gold marts), batch loads via incremental merges and streaming via structured streaming into bronze, idempotent/exactly-once writes, data-quality gates between layers, and freshness + cost monitoring. Serve gold to BI.","signals":["clarifies volume/freshness/cost first","bronze/silver/gold layered lakehouse","idempotent loads + quality gates"],"next":"n2"},"n2":{"id":"n2","kind":"decision","prompt":"Which tables are batch and which are streaming — and how do you decide?","model":"Decide by the freshness SLO and the cost of latency, not by fashion. Nightly/periodic batch (incremental merge) for anything that only needs daily freshness — it''s cheaper and simpler. Structured streaming only where minutes matter (e.g. operational dashboards, fraud signals). Often the same source is streamed into bronze and the gold mart is rebuilt incrementally on a schedule — a hybrid, so you don''t pay streaming cost for batch-tolerant marts.","signals":["freshness SLO + cost drive the choice","batch is the default; stream only where minutes matter","hybrid: stream to bronze, batch the mart"],"next":"n3"},"n3":{"id":"n3","kind":"why","prompt":"Why ELT into the lakehouse rather than transforming before load (classic ETL)?","model":"Landing raw first keeps an immutable, replayable source of truth: you can reprocess when logic changes without re-ingesting, and transforms run on elastic lakehouse compute close to the data. Trade-off: raw storage cost and governance over a larger surface. For heavy pre-load cleansing or strict PII-at-source rules you''d still transform-on-ingest.","signals":["raw landing = replayable source of truth","transform on elastic compute","names when ETL-on-ingest still wins"],"next":"n4"},"n4":{"id":"n4","kind":"constraint","constraint_type":"production","prompt":"A pipeline run is retried after a partial failure. How do you avoid double-counting or corrupting the table?","model":"Make writes idempotent: MERGE on a stable business key (upsert) instead of blind appends, or partition-overwrite the reprocessed window. For streaming, use exactly-once sinks with checkpointing so a replay doesn''t duplicate. Backfills target a bounded window and use the same merge logic as incremental runs. A retried run must converge to the same table state — reruns are safe by design, not by luck.","signals":["MERGE on business key / partition overwrite","checkpointed exactly-once streaming","bounded, same-logic backfill"],"next":"n5"},"n5":{"id":"n5","kind":"constraint","constraint_type":"production","prompt":"How do you stop bad data from silently reaching the gold marts?","model":"Quality gates between layers: schema/type checks, not-null and uniqueness on keys, referential and range/volume checks, and freshness assertions. Fail or quarantine the batch when a gate breaks rather than publishing — route rejects to a dead-letter/quarantine table with the reason, alert, and keep the last-good gold intact. Track row-count deltas so a sudden drop/spike is caught. Silently wrong is worse than visibly late.","signals":["quality gates between layers (keys/nulls/volume/freshness)","quarantine + keep last-good, don''t publish bad","row-count/anomaly tracking + alert"],"next":"n6"},"n6":{"id":"n6","kind":"constraint","constraint_type":"production","prompt":"An upstream source adds and renames columns without warning. How does your pipeline survive it?","model":"Treat bronze as schema-tolerant: ingest with schema evolution/merge so new columns are additive, never a hard crash. Pin the silver/gold contract to the columns you actually consume and map explicitly, so an upstream rename surfaces as a controlled mapping change, not silent data loss. Version the schema and alert on unexpected changes. Additive-safe at the edge, contract-stable in the middle.","signals":["schema-tolerant bronze (additive evolution)","explicit contract/mapping for silver+gold","version + alert on schema change"],"next":"n7"},"n7":{"id":"n7","kind":"incident","prompt":"A Spark job that was fast is now slow and spilling after data growth. Diagnose it.","model":"Read the Spark UI/stages. Usual suspects: data skew on a join/group key (a few huge partitions), small-file explosion from streaming (compact/optimize), shuffle spill from under-partitioning or an undersized cluster, or exploding joins from a grain bug. Fix the specific cause — salt/repartition the skewed key, compact small files, tune shuffle partitions / right-size the cluster, fix the join grain. Don''t just scale the cluster to hide skew.","signals":["reads the Spark UI (skew/spill/small files)","fixes the specific cause (salt/compact/repartition)","doesn''t just upsize to mask skew"],"next":"n8"},"n8":{"id":"n8","kind":"incident","prompt":"Late-arriving events show up hours after their event time. Your real-time dashboard is now wrong. What do you do?","model":"Process on event time, not processing time: use watermarks to bound how late you''ll still accept, and windowed aggregations that update when late data lands. For the dashboard, make the current window provisional and reconcile with the batch (gold) layer so the authoritative number self-corrects — a lambda/kappa-style reconciliation. Communicate ''as of + still settling'' rather than presenting a provisional number as final.","signals":["event-time + watermark for lateness","provisional window reconciled by batch","surface as-of / settling, don''t present provisional as final"],"next":"n9"},"n9":{"id":"n9","kind":"reflection","prompt":"Where did you assert a choice without the mechanism, the trade-off, or the verification?","checklist":["I clarified volume/freshness/cost before designing","I chose batch vs streaming by SLO + cost, not fashion","I made retries idempotent (merge/checkpoint), not append-and-hope","I gated data quality between layers and quarantined bad data","I handled schema evolution with a stable consumed contract","I diagnosed Spark perf by cause (skew/spill/small files), not just upsizing"],"next":"n10"},"n10":{"id":"n10","kind":"next_drill","prompt":"Strong data-engineering defense. Keep going:","recommend":[{"label":"Snowflake Cortex — System Design + Mock","path":"Snowflake-Cortex/system-design-mock.html"},{"label":"Snowflake Cortex — Security, Cost & Observability","path":"Snowflake-Cortex/governance-cost-observability.html"},{"label":"Keep Asking Why — data platform chain","path":"Personal-SourceCode/Interview_Why_Chains.html"}]}}}'::jsonb,
  true
)
